        require(amount == 10);
        require(address(this).balance >= amount);

        uint prePot = c.pot(); if (__ESBMC_reverted()) return;
        uint oldBalance = address(this).balance;

        bool reverted;
        c.play{value: amount}(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
