contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    EtherLotto c;

    function setUp() public {
        c = new EtherLotto();
    }

    function _run(uint256 amount, uint256 extra) internal {
        amount = bound(amount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        amount = 10;
        vm.assume(address(this).balance >= amount);
        uint256 prePot;
        try c.pot() returns (uint256 __r) { prePot = __r; } catch { return; }
        uint oldBalance = address(this).balance;
        bool reverted;
        try c.play{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint256 postPot;
        try c.pot() returns (uint256 __r) { postPot = __r; } catch { return; }
        assertTrue(!reverted && (postPot == prePot + amount || postPot == 0));
    }

    function testFuzz_run(uint256 amount, uint256 extra) public {
        _run(amount, extra);
